interface ConversationState {
  conversations: Map<string, Conversation>;
  activeConversationId: string | null;
  isLoading: boolean;
}

export const useConversationStore = create&lt;ConversationState&gt;()(
  persist(
    (set, get) => ({
      conversations: new Map(),
      activeConversationId: null,
      isLoading: false,

      createConversation: (projectId: string) => {
        const id = crypto.randomUUID();
        const conversation: Conversation = {
          id,
          projectId,
          messages: [],
          createdAt: Date.now(),
          updatedAt: Date.now()
        };
        set(state => {
          const newConversations = new Map(state.conversations);
          newConversations.set(id, conversation);
          return { conversations: newConversations, activeConversationId: id };
        });
        return id;
      },

      loadConversation: async (conversationId: string) => {
        set({ isLoading: true });
        try {
          // Load from IndexedDB via Dexie
          const conversation = await db.conversations.get(conversationId);
          if (conversation) {
            set(state => {
              const newConversations = new Map(state.conversations);
              newConversations.set(conversationId, conversation);
              return {
                conversations: newConversations,
                activeConversationId: conversationId,
                isLoading: false
              };
            });
          }
        } finally {
          set({ isLoading: false });
        }
      },

      addMessage: (conversationId: string, message: Message) => {
        set(state => {
          const conversation = state.conversations.get(conversationId);
          if (!conversation) return state;
          const updated = {
            ...conversation,
            messages: [...conversation.messages, message],
            updatedAt: Date.now()
          };
          const newConversations = new Map(state.conversations);
          newConversations.set(conversationId, updated);
          return { conversations: newConversations };
        });
        // Persist to IndexedDB
        db.conversations.put(get().conversations.get(conversationId));
      }
    }),
    {
      name: 'conversation-storage',
      storage: createJSONStorage(() => localStorage)
    }
  )
);


// Thread persistence layer
interface ThreadRecord {
  id: string;
  projectId: string;
  title: string;
  preview: string;
  createdAt: number;
  updatedAt: number;
  messageCount: number;
  lastMessagePreview: string;
}

class ThreadsStore {
  private db: ThreadsDatabase;

  async getThreads(projectId: string): Promise<ThreadRecord[]> {
    return this.db.threads
      .where('projectId')
      .equals(projectId)
      .sortBy('updatedAt');
  }

  async saveThread(thread: ThreadRecord): Promise<void> {
    await this.db.threads.put(thread);
  }

  async deleteThread(threadId: string): Promise<void> {
    await this.db.threads.delete(threadId);
  }
}
